schema_ddl:
CREATE DOMAIN stato_ordine AS TEXT CHECK (VALUE IN ('in_attesa', 'confermato', 'spedito', 'consegnato', 'annullato'));

CREATE DOMAIN percentuale_sconto AS NUMERIC(5,2) CHECK (VALUE >= 0 AND VALUE <= 100);

CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    email TEXT NOT NULL UNIQUE,
    citta TEXT NOT NULL,
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    descrizione TEXT,
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0),
    giacenza_magazzino INT NOT NULL DEFAULT 0 CHECK (giacenza_magazzino >= 0)
);

CREATE TABLE ordini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id) ON DELETE CASCADE,
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    stato_ordine stato_ordine NOT NULL DEFAULT 'in_attesa',
    importo_totale NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (importo_totale >= 0)
);

CREATE TABLE righe_ordine (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini(id) ON DELETE CASCADE,
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_unitario_riga NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario_riga >= 0),
    sconto percentuale_sconto NOT NULL DEFAULT 0
);
